// This file is generated by AI.

// 资源预览地址的拼接规则。
//
// 预览服务器把项目根挂成站点根, 而 `ensureSite` 返回的前缀已带了 `.../game/{hash}/s/` 会话路径;
// 拼错一个路径段就是**全线 404**, 构建 / 类型检查 / 其它单测都不会有反应, 因此在这里钉住。

import { describe, expect, it } from 'vitest';

import { assetUrlFor } from '../src/lib/assetUrl';

const BASE = 'http://127.0.0.1:34567/abc123/s/';

describe('assetUrlFor', () => {
  it('在站点前缀与相对路径之间补上 game/', () => {
    expect(assetUrlFor(BASE, 'bg/教室.png')).toBe(`${BASE}game/bg/${encodeURIComponent('教室.png')}`);
  });

  it('会话前缀里已经出现过 game 时也不省略（那只是站点路径，不是项目路径）', () => {
    const base = 'http://127.0.0.1:1/some/game/hash/s/';
    expect(assetUrlFor(base, 'figure/a.png')).toBe(`${base}game/figure/a.png`);
  });

  it('把 Windows 反斜杠统一成正斜杠', () => {
    expect(assetUrlFor(BASE, 'bg\\教室.png')).toBe(`${BASE}game/bg/${encodeURIComponent('教室.png')}`);
  });

  it('逐段做 URL 编码', () => {
    // `#`/`?`/空格 这类字符不编码会被当成片段或查询分隔符, 请求直接打不中文件
    expect(assetUrlFor(BASE, 'bg/a #1.png')).toBe(`${BASE}game/bg/${encodeURIComponent('a #1.png')}`);
    expect(assetUrlFor(BASE, 'bg/x?y.png')).toBe(`${BASE}game/bg/${encodeURIComponent('x?y.png')}`);
    // 目录分隔符必须保留成 `/`, 不能被编码成 `%2F`
    expect(assetUrlFor(BASE, 'a/b/c.png')).toBe(`${BASE}game/a/b/c.png`);
  });

  it('去掉相对路径开头多余的分隔符（不产生 `game//bg`）', () => {
    expect(assetUrlFor(BASE, '/bg/a.png')).toBe(`${BASE}game/bg/a.png`);
    expect(assetUrlFor(BASE, '\\bg\\a.png')).toBe(`${BASE}game/bg/a.png`);
  });

  it('站点还没起时返回 undefined（调用方据此显示"预览站点还没就绪"）', () => {
    expect(assetUrlFor(null, 'bg/a.png')).toBeUndefined();
    expect(assetUrlFor(undefined, 'bg/a.png')).toBeUndefined();
    expect(assetUrlFor('', 'bg/a.png')).toBeUndefined();
  });

  it('顶层文件也带 game/', () => {
    expect(assetUrlFor(BASE, 'config.txt')).toBe(`${BASE}game/config.txt`);
  });
});
